// Names are painted into each ribbon; HTML headings remain for accessibility.
const ribbonBadges=[["a319","AIRBUS A319"],["a320","AIRBUS A320"],["a320neo","AIRBUS A320neo"],["a321","AIRBUS A321"],["a321neo","AIRBUS A321neo"],["a330-200","AIRBUS A330-200"],["a330-300","AIRBUS A330-300"],["a350-900","AIRBUS A350-900"],["a380-800","AIRBUS A380-800"],["b737-300","BOEING 737-300"],["b737-800","BOEING 737-800"],["b737-max8","BOEING 737 MAX 8"],["b747-400","BOEING 747-400"],["b767-300","BOEING 767-300"],["b777-300","BOEING 777-300"],["b777-300er","BOEING 777-300ER"],["b787-8","BOEING 787-8"],["b787-9","BOEING 787-9"],["atr72","ATR 72"],["dash8-400","DASH 8-400"],["e195","EMBRAER E195"],["md88","MD-88"],["c919","COMAC C919"]];
function ribbonKey(value){return String(value).toUpperCase().replace(/[^A-Z0-9]/g,'').replace(/^(AIRBUS|BOEING|COMAC)/,'').replace(/^B(?=7\d\d)/,'');}
function aircraftBadge(name){
 const n=String(name).toUpperCase(),key=ribbonKey(name);
 let entry=ribbonBadges.find(([,label])=>ribbonKey(label)===key);
 if(!entry){
  const aliases={A380:'a380-800',A350:'a350-900',A330:'a330-300','737MAX8':'b737-max8',EMBRAER195:'e195',EMBRAERE195:'e195',E195:'e195',MCDONNELLDOUGLASMD88:'md88',DHC8400DASH8Q:'dash8-400',DHC8400:'dash8-400',DEHAVILLANDDASH8400:'dash8-400',DEHAVILLANDDASH8:'dash8-400',DASH8Q400:'dash8-400',ATR72600:'atr72'};
  const alias=aliases[key];if(alias)entry=ribbonBadges.find(([id])=>id===alias);
 }
 const families=[[/380/,'a380'],[/747/,'b747'],[/350/,'a350'],[/330/,'a330'],[/321/,'a321'],[/320/,'a320'],[/319/,'a319'],[/787/,'b787'],[/777/,'b777'],[/767/,'b767'],[/737/,'b737'],[/ATR/,'atr72'],[/DHC|DASH|DE HAVILLAND/,'dash8'],[/EMBRAER|E[ -]?195|ERJ/,'e195'],[/MD[ -]?88|MCDONNELL/,'md88'],[/919|COMAC/,'c919']];
 const family=families.find(([pattern])=>pattern.test(n));
 const img=document.createElement('img');img.src=entry?'assets/aircraft-ribbon/'+entry[0]+'.webp':'assets/aircraft/'+(family?family[1]:'a320')+'.webp';img.alt='';img.loading='lazy';img.decoding='async';img.width=640;img.height=640;
 return {svg:img,palette:['#be8c32','#f4e6c4'],hasLettering:!!entry,description:entry?'机型艺术徽章':'客机艺术示意'};
}
function badgeName(name){return String(name);}
'use strict';
const fleetPage=document.createElement('section');fleetPage.className='fleet-page';fleetPage.hidden=true;fleetPage.innerHTML='<div class="fleet-heading"><div><h2>我的机型收藏册</h2><p id="fleet-count"></p></div><input type="search" id="fleet-search" placeholder="搜索机型" aria-label="搜索机型"></div><p id="fleet-missing"></p><div class="fleet-grid" id="fleet-grid"></div>';document.querySelector('main').append(fleetPage);
const fleetNav=document.createElement('button');fleetNav.type='button';fleetNav.dataset.view='fleet';fleetNav.textContent='机型收藏册';document.querySelector('.view-links').append(fleetNav);
const fleetDialog=document.createElement('dialog');fleetDialog.className='flight-dialog';fleetDialog.innerHTML='<div class="dialog-heading"><h2 id="fleet-detail-title"></h2><button type="button" class="dialog-close" id="fleet-close" aria-label="关闭">×</button></div><div id="fleet-detail"></div>';document.body.append(fleetDialog);$('fleet-close').onclick=()=>fleetDialog.close();
function fleetKey(value){return String(value||'').trim().replace(/\s+/g,' ');}
function fleetGroups(){const groups=new Map();let missing=0;for(const r of state.rows||[]){const date=dateValue(r.date);if(!date||date>localDate()||recordCanceled(r))continue;const name=fleetKey(r.aircraft);if(!name){missing++;continue;}const key=name.toLowerCase();if(!groups.has(key))groups.set(key,{name,rows:[]});groups.get(key).rows.push(r);}return {groups:[...groups.values()].sort((a,b)=>b.rows.length-a.rows.length||a.name.localeCompare(b.name)),missing};}
function fleetSpecial(name){return /\b(?:a?380|b?747)(?:\b|[- ])/i.test(name)||(!/airbus|boeing|\b[ab][2378]\d\d/i.test(name));}
function fleetDetail(g){$('fleet-detail-title').textContent=g.name;const box=$('fleet-detail');box.replaceChildren();for(const r of [...g.rows].sort((a,b)=>dateValue(b.date).localeCompare(dateValue(a.date)))){const row=document.createElement('div');row.className='fleet-leg';const title=document.createElement('strong');title.textContent=`${recordAirportName(r.from)} → ${recordAirportName(r.to)}`;const sub=document.createElement('span');sub.textContent=`${dateValue(r.date)} · ${normalizeAirlineCode(r.airline)} ${r.flight||''} · ${airportCode(r.from)} → ${airportCode(r.to)}`;row.append(title,sub);box.append(row);}fleetDialog.showModal();}
function renderFleet(){const {groups,missing}=fleetGroups(),query=$('fleet-search').value.trim().toLowerCase();$('fleet-count').textContent=`已收藏 ${groups.length} 种机型 · ${groups.reduce((n,g)=>n+g.rows.length,0)} 次飞行`;$('fleet-missing').textContent=missing?`${missing} 条历史行程尚未填写机型，可在航班记录中补齐。`:'';const box=$('fleet-grid');box.replaceChildren();for(const g of groups.filter(g=>g.name.toLowerCase().includes(query))){const button=document.createElement('button');button.type='button';button.className='fleet-card';const art=aircraftBadge(g.name);button.style.setProperty('--badge-color',art.palette[0]);button.style.setProperty('--badge-light',art.palette[1]);const icon=document.createElement('div');icon.className='fleet-icon';icon.append(art.svg);button.title=g.name+' · '+art.description+'（示意图）';button.setAttribute('aria-label',g.name+'，'+g.rows.length+' 次飞行，查看航班记录');const title=document.createElement('h3');title.textContent=badgeName(g.name);if(art.hasLettering)title.className='fleet-name-a11y';const detail=document.createElement('p');const airlines=new Set(g.rows.map(r=>normalizeAirlineCode(r.airline)).filter(Boolean)),routes=new Set(g.rows.map(r=>[airportCode(r.from),airportCode(r.to)].join('→')));detail.textContent=`${g.rows.length} 次飞行`;button.title+=` · ${airlines.size} 家航司 · ${routes.size} 条单向航线`;const dates=g.rows.map(r=>dateValue(r.date)).sort();const first=document.createElement('small');first.textContent=`首次乘坐 ${dates[0]}`;const tag=document.createElement('span');tag.className='fleet-tag';tag.textContent='';tag.hidden=true;button.append(icon,tag,title,detail,first);button.onclick=()=>fleetDetail(g);box.append(button);}if(!box.children.length){const empty=document.createElement('p');empty.textContent=groups.length?'没有匹配的机型。':'添加已飞行且填写了机型的航班，开启你的收藏册。';box.append(empty);}}
const originalShowWorkspace=showWorkspace;showWorkspace=function(view){originalShowWorkspace(view==='fleet'?'records':view);fleetPage.hidden=view!=='fleet';if(view==='fleet'){records.hidden=true;workspace.hidden=true;$('workspace-title').textContent='每一种飞机，一段新的记忆。';$('workspace-description').textContent='从历史行程中收集你乘坐过的机型。';document.querySelectorAll('[data-view]').forEach(b=>{if(b.dataset.view==='fleet')b.setAttribute('aria-current','page');else b.removeAttribute('aria-current');});renderFleet();}};
fleetNav.onclick=()=>showWorkspace('fleet');$('fleet-search').oninput=renderFleet;window.addEventListener('atlas:rows',renderFleet);renderFleet();
